/** Native controls exercise recovered history, current failures and same-task continuation without paid calls. */
async page => {
  const result = {}, errors = [], onError = error => errors.push(error.message)
  const check = (value, name) => { if (!value) throw new Error(name); result[name] = true }
  page.on('pageerror', onError)
  const media = route => route.fulfill({ contentType: 'image/svg+xml', body: '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="240"><rect width="400" height="240" fill="#526956"/></svg>' })
  await page.route('**/api/visual-curator/resource**', media)
  try {
    await page.goto('http://127.0.0.1:3094/')
    await page.setViewportSize({ width: 1440, height: 960 })
    await page.waitForFunction(() => !!window.incrementalFixture)
    await page.evaluate(() => window.incrementalFixture.showDiagnostics('completed'))
    const dialog = page.locator('.vc-analysis-modal')
    await dialog.waitFor()
    check(await dialog.getByRole('tab').count() === 4, 'fourTabs')
    await dialog.getByRole('tab', { name: /^失败诊断/ }).click()
    const diagnostics = dialog.getByRole('tabpanel', { name: /^失败诊断/ })
    await diagnostics.getByText('本次任务已成功完成；以下是此前失败或中断的尝试，保留供追查。', { exact: true }).waitFor()
    check(await diagnostics.locator('.vc-diagnostic-card').count() === 2, 'recoveredHistoryIsDistinct')
    check(await diagnostics.getByText('request-timeout', { exact: true }).count() === 1 && await diagnostics.getByText('cancelled', { exact: true }).count() === 1, 'savedFailureCauses')
    check(await dialog.getByRole('button', { name: '继续分析', exact: true }).count() === 0, 'completedDoesNotReplay')
    await dialog.getByRole('tab', { name: /^请求记录/ }).click()
    check(await dialog.getByRole('tabpanel', { name: /^请求记录/ }).locator('.vc-diagnostic-card').count() === 3, 'allRequestsRemainVisible')
    await dialog.getByRole('button', { name: '查看模型输出', exact: true }).first().click()
    await dialog.locator('.vc-chat-feed:visible').waitFor()
    check(await dialog.locator('[data-selected-batch="true"]').count() > 0, 'locateAttemptOutput')
    await page.evaluate(() => window.incrementalFixture.showDiagnostics('failed'))
    await dialog.getByRole('tab', { name: /^失败诊断/ }).click()
    await dialog.getByRole('heading', { name: '当前任务失败原因', exact: true }).waitFor()
    check(await dialog.getByRole('heading', { name: '当前任务失败原因', exact: true }).count() === 1, 'currentFailureExplained')
    const runId = await page.evaluate(() => window.incrementalFixture.getAnalysisRunId())
    await page.evaluate(() => { window.incrementalFixture.state.holdResume = true })
    await dialog.getByRole('button', { name: '继续分析', exact: true }).click()
    check(await dialog.getByRole('button', { name: '正在继续…', exact: true }).isDisabled(), 'continuationBusyFeedback')
    await page.evaluate(() => window.incrementalFixture.releaseResume())
    await dialog.getByRole('button', { name: '暂停分析', exact: true }).waitFor()
    check(await page.evaluate(() => window.incrementalFixture.getAnalysisRunId()) === runId && await dialog.locator('.vc-chat-count strong').innerText() === '267', 'sameTaskAndCheckpoint')
    check(await page.evaluate(() => window.incrementalFixture.state.resumes) === 1, 'singleContinuation')
    await page.evaluate(() => window.incrementalFixture.showDiagnostics('expired'))
    await dialog.getByText('原任务截止时间已过，请重新开始并复用已保存观察。', { exact: true }).first().waitFor()
    check(await dialog.getByRole('button', { name: '继续分析', exact: true }).count() === 0 && (await dialog.innerText()).includes('原任务截止时间已过'), 'expiredBudgetExplained')
    await page.evaluate(() => window.incrementalFixture.showDiagnostics('completed'))
    await dialog.getByRole('tab', { name: /^失败诊断/ }).click()
    await page.setViewportSize({ width: 390, height: 844 })
    check(await dialog.evaluate(element => element.scrollWidth <= element.clientWidth && document.documentElement.scrollWidth <= innerWidth), 'narrowLayoutFits')
    await page.evaluate(() => window.incrementalFixture.showDiagnostics('failed'))
    await dialog.getByRole('button', { name: '继续分析', exact: true }).waitFor()
    check(await dialog.getByRole('button', { name: '继续分析', exact: true }).isVisible() && await dialog.evaluate(element => element.scrollWidth <= element.clientWidth), 'narrowContinuationFits')
    await page.evaluate(() => window.incrementalFixture.showDiagnostics('completed'))
    await page.evaluate(() => window.incrementalFixture.theme(false))
    check(await diagnostics.locator('.vc-diagnostic-card').first().evaluate(element => getComputedStyle(element).backgroundColor !== 'rgba(0, 0, 0, 0)'), 'nativeLightTheme')
    await page.setViewportSize({ width: 1440, height: 960 })
    await page.evaluate(() => { window.incrementalFixture.theme(true); window.incrementalFixture.showProfile() })
    const rail = page.locator('.vc-profile-dock .vc-profile-actions'), range = page.locator('.vc-analysis-start-modal')
    await rail.getByText('已取消，已保留', { exact: false }).waitFor()
    check(await rail.locator('[data-gallery-task]').count() === 1 && await page.locator('.vc-library-pane [data-gallery-task]').count() === 0, 'endedImportStatusInRailOnly')
    check(await rail.getByRole('button', { name: '继续分析', exact: true }).isEnabled() && await rail.getByRole('button', { name: '重新分析', exact: true }).isEnabled(), 'readyProfileKeepsBothActions')
    await rail.getByRole('button', { name: '重新分析', exact: true }).click()
    await range.getByRole('button', { name: /^全部重新分析/ }).waitFor()
    check(await page.evaluate(() => window.incrementalFixture.state.launches.length) === 0, 'reanalysisRequiresConfirmation')
    await range.getByRole('button', { name: '取消', exact: true }).click()
    await page.evaluate(() => window.incrementalFixture.advance())
    check(await range.count() === 0 && await page.evaluate(() => window.incrementalFixture.state.launches.length) === 0, 'cancelDoesNotStartAnalysis')
    await rail.getByRole('button', { name: '分析过程', exact: true }).click()
    await dialog.getByRole('button', { name: '重新分析', exact: true }).waitFor()
    check(await dialog.locator('.vc-process-title').evaluate(element => {
      const title = element.querySelector('h2').getBoundingClientRect(), name = element.querySelector('p').getBoundingClientRect()
      return Math.min(title.bottom, name.bottom) > Math.max(title.top, name.top) && element.parentElement.getBoundingClientRect().height <= 72
    }), 'compactInlineAnalysisHeading')
    await dialog.getByRole('button', { name: '重新分析', exact: true }).click()
    await range.getByRole('button', { name: /^全部重新分析/ }).waitFor()
    check(await dialog.count() === 0 && await page.evaluate(() => window.incrementalFixture.state.launches.length) === 0, 'processReanalysisUsesRangeConfirmation')
    await range.getByRole('button', { name: /^全部重新分析/ }).click()
    await page.waitForFunction(() => window.incrementalFixture.state.launches.length === 1)
    check(await page.evaluate(() => {
      const launch = window.incrementalFixture.state.launches[0]
      return launch.analysisMode === 'all' && launch.planDigest === 'confirmed-plan' && launch.buildDataset === true
    }), 'confirmedFullAnalysisUsesOriginalPreflight')
    await page.getByRole('tab', { name: '找图与裁剪', exact: true }).click()
    await page.getByRole('tab', { name: '参考与画像', exact: true }).click()
    check(await range.count() === 0, 'consumedReanalysisDoesNotReplay')
    await rail.getByRole('button', { name: '继续分析', exact: true }).click()
    await range.getByRole('button', { name: /^分析待处理图片/ }).click()
    await page.waitForFunction(() => window.incrementalFixture.state.launches.length === 2)
    check(await page.evaluate(() => window.incrementalFixture.state.launches[1].analysisMode === 'pending' && window.incrementalFixture.state.imports.length === 0), 'endedTaskContinuationUsesPendingWithoutReimport')
    await page.evaluate(() => window.incrementalFixture.showProfile('failed'))
    const resumes = await page.evaluate(() => window.incrementalFixture.state.resumes)
    await rail.getByRole('button', { name: '继续分析', exact: true }).click()
    await page.waitForFunction(value => window.incrementalFixture.state.resumes === value + 1, resumes)
    check(await page.evaluate(() => window.incrementalFixture.state.launches.length) === 2, 'recoverableProfileResumesSameRun')
    await page.evaluate(() => window.incrementalFixture.showProfile('completed', 'running'))
    await page.locator('.vc-library-pane [data-gallery-task]').waitFor()
    check(await rail.locator('[data-gallery-task]').count() === 0 && await rail.getByRole('button', { name: '继续分析', exact: true }).isDisabled(), 'activeImportKeepsGridProgressAndBlocksStart')
    await page.evaluate(() => window.incrementalFixture.showProfile())
    await page.setViewportSize({ width: 390, height: 844 })
    await page.getByRole('button', { name: '风格画像', exact: true }).click()
    const compactRail = page.locator('.vc-profile-modal .vc-profile-actions')
    await compactRail.getByText('已取消，已保留', { exact: false }).waitFor()
    check(await compactRail.getByRole('button', { name: '继续分析', exact: true }).isVisible() && await page.locator('.vc-profile-modal').evaluate(element => element.scrollWidth <= element.clientWidth), 'compactProfileKeepsStatusAndContinuation')
    await page.locator('.vc-profile-modal').getByRole('button', { name: '关闭', exact: true }).click()
    await page.evaluate(() => window.incrementalFixture.showDiagnostics('completed', '很长的素材集名称'.repeat(24)))
    await dialog.getByRole('button', { name: '重新分析', exact: true }).waitFor()
    check(await dialog.locator('.vc-process-title').evaluate(element => {
      const name = element.querySelector('p'), style = getComputedStyle(name)
      return name.scrollWidth > name.clientWidth && style.textOverflow === 'ellipsis' && style.whiteSpace === 'nowrap'
    }) && await dialog.evaluate(element => element.scrollWidth <= element.clientWidth && document.documentElement.scrollWidth <= innerWidth), 'longInlineNameFitsCompactDialog')
    await page.setViewportSize({ width: 1440, height: 960 })
    await page.evaluate(() => { window.incrementalFixture.showProfile(); window.incrementalFixture.advanceAnalysisProgress() })
    const progress = page.locator('.vc-collection-context .vc-analysis-header')
    check(await progress.count() === 1 && (await progress.getAttribute('aria-label')).includes('4 / 267'), 'analysisProgressInCollectionHeader')
    check(await rail.locator('[data-gallery-task]').count() === 0, 'analysisHidesEndedImportStatus')
    await progress.click()
    await dialog.getByRole('button', { name: '暂停分析', exact: true }).waitFor()
    check(await dialog.locator('.vc-chat-count strong').innerText() === '4', 'analysisHeaderOpensSavedProcess')
    await dialog.locator('.vc-chat-footer').getByRole('button', { name: '关闭', exact: true }).click()
    await page.setViewportSize({ width: 390, height: 844 })
    check(await progress.isVisible() && await page.locator('.vc-page-frame').evaluate(element => element.scrollWidth <= element.clientWidth && document.documentElement.scrollWidth <= innerWidth), 'analysisProgressFitsNarrowHeader')
    await page.setViewportSize({ width: 1440, height: 960 })
    await page.evaluate(() => window.incrementalFixture.showProfile())
    await rail.locator('[data-gallery-task]').waitFor()
    check(await progress.count() === 0 && await rail.locator('[data-gallery-task]').count() === 1, 'endedAnalysisRestoresImportNotice')
    result.errors = errors
    if (errors.length) throw new Error(errors.join('; '))
    const expected = await page.evaluate(async () => (await fetch('/analysis-diagnostics-ui.expected.json')).json())
    if (JSON.stringify(result) !== JSON.stringify(expected)) throw new Error(JSON.stringify({ expected, actual: result }))
    return result
  } finally { page.off('pageerror', onError); await page.unroute('**/api/visual-curator/resource**', media) }
}
